import{_ as i,o as n,c as e,a2 as l}from"./chunks/framework.DBU8LMUS.js";const h=JSON.parse('{"title":"Pemecahan Masalah","description":"","frontmatter":{"title":"Pemecahan Masalah","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/troubleshooting.md","filePath":"latest/troubleshooting.md","lastUpdated":1786334463000}'),t={name:"latest/troubleshooting.md"};function u(r,a,s,k,d,o){return n(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="pemecahan-masalah" tabindex="-1">Pemecahan Masalah <a class="header-anchor" href="#pemecahan-masalah" aria-label="Permalink to &quot;Pemecahan Masalah&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Halaman ini berisi solusi untuk kendala umum yang mungkin Anda alami saat menggunakan aplikasi ILUNI FT ELEKTRO UNPAK.</p><h2 id="tidak-menerima-email-verifikasi" tabindex="-1">Tidak Menerima Email Verifikasi <a class="header-anchor" href="#tidak-menerima-email-verifikasi" aria-label="Permalink to &quot;Tidak Menerima Email Verifikasi&quot;">​</a></h2><h3 id="kemungkinan-penyebab" tabindex="-1">Kemungkinan Penyebab <a class="header-anchor" href="#kemungkinan-penyebab" aria-label="Permalink to &quot;Kemungkinan Penyebab&quot;">​</a></h3><ul><li>Email masuk ke folder <strong>spam</strong> atau <strong>promosi</strong>.</li><li>Alamat email yang didaftarkan salah ketik.</li><li>Email verifikasi kadaluwarsa.</li></ul><h3 id="solusi" tabindex="-1">Solusi <a class="header-anchor" href="#solusi" aria-label="Permalink to &quot;Solusi&quot;">​</a></h3><ol><li>Periksa folder spam/promosi pada kotak masuk Anda.</li><li>Pastikan alamat email yang didaftarkan benar.</li><li>Ulangi proses pendaftaran atau minta tautan verifikasi baru.</li><li>Jika tetap tidak diterima, hubungi admin untuk bantuan.</li></ol><h2 id="lupa-kata-sandi" tabindex="-1">Lupa Kata Sandi <a class="header-anchor" href="#lupa-kata-sandi" aria-label="Permalink to &quot;Lupa Kata Sandi&quot;">​</a></h2><ol><li>Buka halaman masuk dan klik <strong>Lupa kata sandi?</strong>.</li><li>Masukkan email terdaftar, lalu klik <strong>Kirim Tautan Atur Ulang</strong>.</li><li>Buka email dan klik tautan atur ulang.</li><li>Buat kata sandi baru dan masuk kembali.</li></ol><h2 id="tidak-bisa-masuk-ke-akun" tabindex="-1">Tidak Bisa Masuk ke Akun <a class="header-anchor" href="#tidak-bisa-masuk-ke-akun" aria-label="Permalink to &quot;Tidak Bisa Masuk ke Akun&quot;">​</a></h2><h3 id="kemungkinan-penyebab-1" tabindex="-1">Kemungkinan Penyebab <a class="header-anchor" href="#kemungkinan-penyebab-1" aria-label="Permalink to &quot;Kemungkinan Penyebab&quot;">​</a></h3><ul><li>Kata sandi salah.</li><li>Email belum diverifikasi.</li><li>Akun dinonaktifkan oleh admin.</li></ul><h3 id="solusi-1" tabindex="-1">Solusi <a class="header-anchor" href="#solusi-1" aria-label="Permalink to &quot;Solusi&quot;">​</a></h3><ol><li>Gunakan fitur <strong>Lupa kata sandi</strong> untuk mengatur ulang.</li><li>Pastikan email sudah diverifikasi (lihat bagian verifikasi di atas).</li><li>Jika akun dinonaktifkan, hubungi admin untuk informasi lebih lanjut.</li></ol><h2 id="halaman-tidak-bisa-dibuka-dialihkan-ke-halaman-masuk" tabindex="-1">Halaman Tidak Bisa Dibuka / Dialihkan ke Halaman Masuk <a class="header-anchor" href="#halaman-tidak-bisa-dibuka-dialihkan-ke-halaman-masuk" aria-label="Permalink to &quot;Halaman Tidak Bisa Dibuka / Dialihkan ke Halaman Masuk&quot;">​</a></h2><p>Beberapa halaman memerlukan akun yang masuk (lihat daftar di <a href="/webapps/latest/mulai">Memulai</a>). Jika Anda sudah masuk tetapi tetap dialihkan:</p><ol><li>Pastikan Anda masuk dengan akun yang benar.</li><li>Muat ulang halaman (refresh).</li><li>Jika halaman admin yang dituju, pastikan akun Anda memiliki peran admin yang sesuai.</li></ol><h2 id="tidak-dapat-membuat-lowongan-atau-pengumuman" tabindex="-1">Tidak Dapat Membuat Lowongan atau Pengumuman <a class="header-anchor" href="#tidak-dapat-membuat-lowongan-atau-pengumuman" aria-label="Permalink to &quot;Tidak Dapat Membuat Lowongan atau Pengumuman&quot;">​</a></h2><p>Fitur ini hanya tersedia untuk <strong>alumni yang profilnya sudah terverifikasi</strong>.</p><ol><li>Periksa status verifikasi pada halaman profil Anda.</li><li>Jika belum terverifikasi, lengkapi profil lalu hubungi admin untuk verifikasi.</li></ol><h2 id="resume-gagal-diunggah" tabindex="-1">Resume Gagal Diunggah <a class="header-anchor" href="#resume-gagal-diunggah" aria-label="Permalink to &quot;Resume Gagal Diunggah&quot;">​</a></h2><ul><li>Pastikan berkas berformat <strong>PDF</strong>.</li><li>Pastikan ukuran berkas <strong>tidak lebih dari 2 MB</strong>. Perkecil berkas terlebih dahulu jika perlu.</li></ul><h2 id="tidak-dapat-membuat-thread-atau-membalas-di-grup" tabindex="-1">Tidak Dapat Membuat Thread atau Membalas di Grup <a class="header-anchor" href="#tidak-dapat-membuat-thread-atau-membalas-di-grup" aria-label="Permalink to &quot;Tidak Dapat Membuat Thread atau Membalas di Grup&quot;">​</a></h2><p>Forum diskusi hanya untuk <strong>anggota grup</strong>.</p><ol><li>Buka halaman grup.</li><li>Klik tombol <strong>Gabung</strong> untuk menjadi anggota.</li><li>Coba buat thread atau balasan kembali.</li></ol><h2 id="tidak-dapat-memberikan-suara-pada-polling" tabindex="-1">Tidak Dapat Memberikan Suara pada Polling <a class="header-anchor" href="#tidak-dapat-memberikan-suara-pada-polling" aria-label="Permalink to &quot;Tidak Dapat Memberikan Suara pada Polling&quot;">​</a></h2><p>Setiap pengguna hanya dapat memilih <strong>sekali</strong> per polling. Jika polling sudah pernah Anda ikuti, tombol suara terkunci. Polling yang sudah berakhir juga tidak menerima suara baru.</p><h2 id="foto-galeri-gagal-diunggah" tabindex="-1">Foto Galeri Gagal Diunggah <a class="header-anchor" href="#foto-galeri-gagal-diunggah" aria-label="Permalink to &quot;Foto Galeri Gagal Diunggah&quot;">​</a></h2><ul><li>Gunakan format gambar standar (JPG, PNG, WebP).</li><li>Pastikan koneksi internet stabil.</li><li>Coba unggah ulang setelah beberapa saat.</li></ul><h2 id="tampilan-aplikasi-tidak-sesuai" tabindex="-1">Tampilan Aplikasi Tidak Sesuai <a class="header-anchor" href="#tampilan-aplikasi-tidak-sesuai" aria-label="Permalink to &quot;Tampilan Aplikasi Tidak Sesuai&quot;">​</a></h2><ol><li>Muat ulang halaman (Ctrl/Cmd + R).</li><li>Kosongkan cache peramban.</li><li>Coba peramban lain atau mode penyamaran.</li></ol><h2 id="menghubungi-admin" tabindex="-1">Menghubungi Admin <a class="header-anchor" href="#menghubungi-admin" aria-label="Permalink to &quot;Menghubungi Admin&quot;">​</a></h2><p>Jika kendala tidak terselesaikan:</p><ul><li>Jelaskan masalah yang dialami beserta langkah yang sudah dicoba.</li><li>Sertakan pesan kesalahan (jika ada) dan tanggal kejadian.</li><li>Hubungi admin melalui kanal resmi komunitas ILUNI FT ELEKTRO UNPAK.</li></ul>',35)])])}const g=i(t,[["render",u]]);export{h as __pageData,g as default};
